UPDATE historical_teams SET
  wins = (SELECT COUNT(*) FROM historical_games g WHERE g.season_id = 16 AND g.away_score IS NOT NULL
    AND ((g.away_team_id = 110 AND g.away_score > g.home_score) OR (g.home_team_id = 110 AND g.home_score > g.away_score))),
  losses = (SELECT COUNT(*) FROM historical_games g WHERE g.season_id = 16 AND g.away_score IS NOT NULL
    AND ((g.away_team_id = 110 AND g.away_score < g.home_score) OR (g.home_team_id = 110 AND g.home_score < g.away_score))),
  runs_scored = (SELECT COALESCE(SUM(CASE WHEN g.away_team_id = 110 THEN g.away_score ELSE g.home_score END), 0)
    FROM historical_games g WHERE g.season_id = 16 AND g.away_score IS NOT NULL AND 110 IN (g.away_team_id, g.home_team_id)),
  runs_allowed = (SELECT COALESCE(SUM(CASE WHEN g.away_team_id = 110 THEN g.home_score ELSE g.away_score END), 0)
    FROM historical_games g WHERE g.season_id = 16 AND g.away_score IS NOT NULL AND 110 IN (g.away_team_id, g.home_team_id))
WHERE id = 110;
UPDATE historical_teams SET
  wins = (SELECT COUNT(*) FROM historical_games g WHERE g.season_id = 16 AND g.away_score IS NOT NULL
    AND ((g.away_team_id = 105 AND g.away_score > g.home_score) OR (g.home_team_id = 105 AND g.home_score > g.away_score))),
  losses = (SELECT COUNT(*) FROM historical_games g WHERE g.season_id = 16 AND g.away_score IS NOT NULL
    AND ((g.away_team_id = 105 AND g.away_score < g.home_score) OR (g.home_team_id = 105 AND g.home_score < g.away_score))),
  runs_scored = (SELECT COALESCE(SUM(CASE WHEN g.away_team_id = 105 THEN g.away_score ELSE g.home_score END), 0)
    FROM historical_games g WHERE g.season_id = 16 AND g.away_score IS NOT NULL AND 105 IN (g.away_team_id, g.home_team_id)),
  runs_allowed = (SELECT COALESCE(SUM(CASE WHEN g.away_team_id = 105 THEN g.home_score ELSE g.away_score END), 0)
    FROM historical_games g WHERE g.season_id = 16 AND g.away_score IS NOT NULL AND 105 IN (g.away_team_id, g.home_team_id))
WHERE id = 105;

-- The series ended 4-1, so these two were never played.
UPDATE historical_games SET status = 'NOT_NEEDED' WHERE season_id = 16 AND source_game_id IN ('WS-G6', 'WS-G7');
